<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{AuthController,DashboardController,LearningController,QuizController,PracticeController,DocumentController,ForumController};
use App\Http\Controllers\Admin\{DashboardController as AdminDashboard,ProgramController as AdminPrograms,UserController as AdminUsers,EnrollmentController as AdminEnrollments,SectionController as AdminSections,ReviewController as AdminReview,GroupController as AdminGroups,DocumentAdminController as AdminDocuments,AnnouncementController as AdminAnnouncements}; use App\Http\Controllers\Curator\DashboardController as CuratorDashboard;
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.perform');});Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){Route::get('/',[DashboardController::class,'index'])->name('dashboard');Route::get('/learning',[LearningController::class,'index'])->name('learning.index');Route::get('/learning/{section}',[LearningController::class,'show'])->name('learning.show');Route::get('/quizzes',[QuizController::class,'index'])->name('quizzes.index');Route::get('/quizzes/{quiz}',[QuizController::class,'show'])->name('quizzes.show');Route::post('/quizzes/{quiz}',[QuizController::class,'submit'])->name('quizzes.submit');Route::get('/practice',[PracticeController::class,'index'])->name('practice.index');Route::get('/documents',[DocumentController::class,'index'])->name('documents.index');Route::get('/forum',[ForumController::class,'index'])->name('forum.index');
Route::prefix('curator')->name('curator.')->middleware('role:curator,admin')->group(function(){Route::get('/',[CuratorDashboard::class,'index'])->name('dashboard');Route::get('/review',[AdminReview::class,'index'])->name('review');Route::patch('/review/submission/{submission}',[AdminReview::class,'submission'])->name('review.submission');Route::patch('/review/final/{finalWork}',[AdminReview::class,'finalWork'])->name('review.final');});
Route::prefix('admin')->name('admin.')->middleware('role:admin')->group(function(){Route::get('/',[AdminDashboard::class,'index'])->name('dashboard');Route::resource('programs',AdminPrograms::class)->except('show');Route::resource('users',AdminUsers::class)->except('show');Route::resource('groups',AdminGroups::class)->only(['index','store','update','destroy']);Route::get('/enrollments',[AdminEnrollments::class,'index'])->name('enrollments.index');Route::patch('/enrollments/{enrollment}',[AdminEnrollments::class,'update'])->name('enrollments.update');Route::post('/enrollments/{enrollment}/complete',[AdminEnrollments::class,'complete'])->name('enrollments.complete');Route::resource('sections',AdminSections::class)->only(['index','store','update','destroy']);Route::get('/review',[AdminReview::class,'index'])->name('review.index');Route::patch('/review/submission/{submission}',[AdminReview::class,'submission'])->name('review.submission');Route::patch('/review/final/{finalWork}',[AdminReview::class,'finalWork'])->name('review.final');Route::resource('documents',AdminDocuments::class)->only(['index','store','destroy']);Route::resource('announcements',AdminAnnouncements::class)->only(['index','store','update','destroy']);});});